<template><div class="student-page"><header class="heading"><div><p>MY SCORES</p><h1>我的成绩</h1><span>查看已发布的个人成绩和团队贡献</span></div></header><div v-if="errorMessage" class="error">{{ errorMessage }}</div><section class="panel"><div class="panel-head"><h2>成绩记录</h2><span>{{ scores.length }} 条</span></div><div v-for="item in scores" :key="item.scoreResultId" class="score-row"><div><strong>{{ item.assignmentTitle }}</strong><small>{{ item.courseName }} · {{ item.groupName || '未分组' }}</small></div><div><span>贡献 {{ ratio(item.contribution) }}</span><b>{{ item.finalScore == null ? '未发布' : Number(item.finalScore).toFixed(2) }}</b></div></div><el-empty v-if="!scores.length" description="暂无已发布成绩" /></section></div></template>
<script setup>
import { onMounted,ref } from 'vue';import { ElEmpty } from 'element-plus';import { getScores } from '@/api/student';import { getErrorMessage } from '@/api/response';const scores=ref([]);const errorMessage=ref('');const ratio=v=>v==null?'—':`${(Number(v)*100).toFixed(1)}%`;onMounted(async()=>{try{scores.value=await getScores()}catch(e){errorMessage.value=getErrorMessage(e,'成绩加载失败')}})
</script>
<style scoped>.student-page{max-width:1120px;margin:0 auto}.heading{margin-bottom:28px}.heading p{margin:0 0 8px;color:#6b9ed8;font-size:11px;letter-spacing:1.5px}.heading h1{margin:0 0 8px;color:#263b53;font-size:30px}.heading span{color:#8795a6}.panel{overflow:hidden;border-radius:9px;background:#fff;box-shadow:0 3px 12px rgba(38,59,83,.06)}.panel-head{display:flex;justify-content:space-between;padding:19px 22px;border-bottom:1px solid #edf1f4}.panel-head h2{margin:0;color:#263b53;font-size:18px}.panel-head span{color:#6b9ed8}.score-row{display:flex;align-items:center;justify-content:space-between;padding:18px 22px;border-bottom:1px solid #edf1f4}.score-row strong,.score-row small{display:block}.score-row strong{color:#334155}.score-row small{margin-top:6px;color:#98a5b3;font-size:12px}.score-row div:last-child{display:grid;gap:6px;text-align:right;color:#8795a6;font-size:12px}.score-row b{color:#356798;font-size:22px}.error{padding:14px;color:#b42318;background:#fff5f5}</style>
